import{_ as a,o as n,c as t,ag as i}from"./chunks/framework.CmaAMB6e.js";const c=JSON.parse('{"title":"25 · 成本与容量优化","description":"","frontmatter":{"概念":"成本与容量优化","技能":"system-design","阶段":"5-资深架构","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z","前置":"24 大规模系统演进","耗时":"1.5~2 小时"},"headers":[],"relativePath":"system-design/concepts/25-cost-optimization.md","filePath":"system-design/concepts/25-cost-optimization.md","lastUpdated":null}'),e={name:"system-design/concepts/25-cost-optimization.md"};function p(l,s,h,r,o,d){return n(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="_25-·-成本与容量优化" tabindex="-1">25 · 成本与容量优化 <a class="header-anchor" href="#_25-·-成本与容量优化" aria-label="Permalink to &quot;25 · 成本与容量优化&quot;">​</a></h1><blockquote><p><strong>前置</strong>：24 大规模系统演进 · <strong>预计</strong>：1.5~2 小时</p></blockquote><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>系统设计课程通常只教「怎么做大」,却很少教「怎么省钱」——而<strong>成本是架构决策的硬约束</strong>:老板关心的不是你的架构图多漂亮,而是「这套系统跑一年要多少钱」。云计算的按需计费把成本从「预算内的一次性采购」变成「持续滴答作响的仪表盘」:每个实例、每 GB 存储、每 GB 流量都在实时产生费用。架构师必须建立<strong>成本意识</strong>:理解资源利用率、预留 vs 按需的计价博弈、容量规划的预测艺术,以及「降本」到底该先优化什么。</p><p>成本优化的第一性原理是:<strong>只为「必要的容量」付费,且不因容量不足失去业务</strong>。这要求把成本拆到单位经济(每请求成本、每用户成本),用数据说话——没有基线的优化都是表演。优化手段(缓存、压缩、批处理、预留实例)本身也要消耗工程师时间,所以<strong>ROI 判断</strong>是成本优化的最高级能力:不是「能不能省」,而是「值不值得省」。</p><p>对前端工程师:你其实一直在做成本优化——bundle 体积预算、代码分割、图片压缩、缓存策略,本质都是「在用户体验不变的前提下减少资源消耗」。后端云成本优化是同一件事的放大版:每次节省的不再是 KB,而是按 GB/小时计费的云账单。前端优化看 Lighthouse 分数,后端优化看成本报告——方法论完全一致。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-成本意识-单位经济与资源利用率" tabindex="-1">1. 成本意识:单位经济与资源利用率 <a class="header-anchor" href="#_1-成本意识-单位经济与资源利用率" aria-label="Permalink to &quot;1. 成本意识:单位经济与资源利用率&quot;">​</a></h4><p>把成本从「总账单」拆到<strong>单位成本</strong>,才能真正驱动决策:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>月度账单结构(示例):</span></span>
<span class="line"><span>├── 计算(ECS/容器)       ¥3,000   ← 最大头,利用率是核心指标</span></span>
<span class="line"><span>├── 存储(数据库/对象存储) ¥1,200</span></span>
<span class="line"><span>├── 网络(带宽/流量)       ¥800    ← 容易被忽略的隐形费用</span></span>
<span class="line"><span>├── 中间件(消息/缓存/CDN) ¥1,000</span></span>
<span class="line"><span>└── 合计                 ¥6,000</span></span>
<span class="line"><span></span></span>
<span class="line"><span>单位经济:</span></span>
<span class="line"><span>├── 每百万请求成本 = 账单 / 请求量</span></span>
<span class="line"><span>├── 每活跃用户成本 = 账单 / MAU(获客成本的对照基准)</span></span>
<span class="line"><span>└── 利用率 = 实际用量 / 付费量(如 CPU 平均 40% = 浪费 60%)</span></span></code></pre></div><p><strong>核心纪律:一切优化先看利用率</strong>——云厂商最贵的不是「贵的东西」,而是「买了不用」的东西。90% 的降本项目从「删掉闲置资源」开始:僵尸实例、无人访问的测试库、无人用的保留 IP。</p><h4 id="_2-预留-vs-按需-云计价的博弈" tabindex="-1">2. 预留 vs 按需:云计价的博弈 <a class="header-anchor" href="#_2-预留-vs-按需-云计价的博弈" aria-label="Permalink to &quot;2. 预留 vs 按需:云计价的博弈&quot;">​</a></h4><table tabindex="0"><thead><tr><th>计费模式</th><th>折扣</th><th>代价</th><th>适用</th></tr></thead><tbody><tr><td>按需(On-Demand)</td><td>0%</td><td>随开随停,灵活</td><td>弹性负载、短期任务</td></tr><tr><td>预留实例(Reserved)</td><td>40-70%</td><td>承诺 1-3 年,不可退</td><td>稳态负载(核心服务)</td></tr><tr><td>竞价实例(Spot)</td><td>80-90%</td><td>随时可能被回收</td><td>批处理、无状态任务、CI</td></tr></tbody></table><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 成本决策模型:混合策略(伪代码)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> instance_strategy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(predicted_load, steady_load):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> steady_load                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 基线负载 → 预留实例(锁死成本)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    buffer </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> predicted_load </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 可预测的波动 → 按需</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    burst </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> predicted_load </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> buffer  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 突发(秒杀/大促) → 竞价/弹性</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;reserved&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: base, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;on_demand&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: buffer, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;spot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: burst}</span></span></code></pre></div><p>经验法则:<strong>稳态负载上预留、波动负载上按需、无状态突发上竞价</strong>,三层混合通常能省 30-50%。前端类比:预留 ≈ 常驻的 bundle 缓存,竞价 ≈ 动态 import 的按需加载。</p><h4 id="_3-容量规划-预测的艺术" tabindex="-1">3. 容量规划:预测的艺术 <a class="header-anchor" href="#_3-容量规划-预测的艺术" aria-label="Permalink to &quot;3. 容量规划:预测的艺术&quot;">​</a></h4><p>容量规划回答「买多少」:买多了浪费钱,买少了丢请求。方法:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>容量规划公式:</span></span>
<span class="line"><span>  峰值 QPS = 平均 QPS × 峰值系数(通常 3-10,按业务波动)</span></span>
<span class="line"><span>  实例数 = 峰值 QPS / 单实例支撑 QPS × 冗余系数(1.5-2,含故障容错)</span></span>
<span class="line"><span>  存储量 = 日增量 × 保留天数 × 膨胀系数(索引、副本、临时数据)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>验证手段:</span></span>
<span class="line"><span>  1. 压测:单实例真实支撑 QPS(不是拍脑袋)</span></span>
<span class="line"><span>  2. 预留水位:只用到 60-70%,留出突发与故障余量</span></span>
<span class="line"><span>  3. 定期复盘:容量 vs 实际,回填预测误差</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>示例:每秒 2000 订单、单实例 500 QPS、冗余 2 倍</span></span>
<span class="line"><span>  → 订单服务实例数 = (2000 × 3 峰值系数) / 500 × 2 = 24 台</span></span></code></pre></div><p><strong>关键认知:容量规划不是精确科学,而是「预测 + 弹性」的组合</strong>——预测定基线,弹性(自动扩缩容)兜波动。预测可以错,没有弹性才致命。</p><h4 id="_4-降本三板斧-缓存、压缩、批处理" tabindex="-1">4. 降本三板斧:缓存、压缩、批处理 <a class="header-anchor" href="#_4-降本三板斧-缓存、压缩、批处理" aria-label="Permalink to &quot;4. 降本三板斧:缓存、压缩、批处理&quot;">​</a></h4><p>按「收益/成本」排序,前三个杠杆几乎永远值得先做:</p><ul><li><strong>缓存</strong>:一次计算/存储的钱,换来 N 次命中。读多写少是缓存的天堂(07 篇)。口径:<strong>缓存命中率 90%+,流量成本降一个数量级</strong>;</li><li><strong>压缩</strong>:数据压缩传输(HTTP 压缩、列存压缩、图片/视频转码),带宽成本是持续性的,压缩是一次性工程投入;</li><li><strong>批处理</strong>:把 N 次小请求合并为 1 次大请求(消息批量消费、批量写库),减少请求数与事务数——<strong>Kafka 批量消费就是最典型的批处理降本</strong>。</li></ul><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 批量消费示例:一次拉取 1000 条消息批处理,而非逐条</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> consume_batch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mq, db):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    batch </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mq.poll(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">max_records</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 批量拉取,降低网络往返</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    db.insert_many(batch)                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 批量写库,事务数减少 1000 倍</span></span></code></pre></div><h4 id="_5-优化-roi-何时值得优化" tabindex="-1">5. 优化 ROI:何时值得优化 <a class="header-anchor" href="#_5-优化-roi-何时值得优化" aria-label="Permalink to &quot;5. 优化 ROI:何时值得优化&quot;">​</a></h4><p>优化本身有成本(工程师时间、上线风险),ROI 判断是成本优化的最高级能力:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ROI 评估清单:</span></span>
<span class="line"><span>  1. 现状基线是什么?(没有数据,一切免谈)</span></span>
<span class="line"><span>  2. 预计年节省多少?(钱 or 资源量,不是百分比)</span></span>
<span class="line"><span>  3. 实施成本多少?(人天 × 人天单价)</span></span>
<span class="line"><span>  4. 风险多大?(影响面、回滚难度)</span></span>
<span class="line"><span>  5. 机会成本:同样的时间做别的优化收益更大?</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>示例判断:</span></span>
<span class="line"><span>  优化 A:重构订单模块 → 省 ¥2,000/年,耗时 20 人天 → ROI 低,不做</span></span>
<span class="line"><span>  优化 B:未用资源清理 + 预留实例 → 省 ¥120,000/年,耗时 2 人天 → ROI 极高,立刻做</span></span></code></pre></div><p><strong>原则:先做「一劳永逸」的治理型优化(清理/预留/压缩),再做「需要持续维护」的结构型优化(重构/改造)</strong>。数字说话,不做没有基线的「感觉型优化」。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>只看单价不看总成本</strong>:单台便宜但数量膨胀,总账单反而更高——永远算总成本与单位成本。</li><li><strong>预留过量</strong>:为「可能用到」预留大量实例,锁死 1-3 年成本,利用率却只有 30%。</li><li><strong>为省钱牺牲可用性</strong>:砍掉冗余、砍掉监控,省的钱不够一次故障的赔偿。</li><li><strong>优化没有基线</strong>:没有压测和监控数据就谈优化,等于在黑暗中开枪。</li><li><strong>容量规划拍脑袋</strong>:单实例能力没压测过,实例数凭感觉,大促直接打爆。</li><li><strong>忽略隐性成本</strong>:跨机房流量费、日志存储、快照、冷数据——这些账单角落里的小项目常常比想象中大。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>:为一个「日活 10 万、QPS 峰值 2000」的读多写少系统做容量估算:实例数、存储量、带宽,并标注稳态/波动/突发各用哪种计费模式。</li><li><strong>进阶</strong>:设计一套「缓存 + 压缩 + 批量消费」的降本方案:给出命中率目标、压缩比目标、批量大小,并估算每月节省金额。</li><li><strong>综合</strong>:为一家公司做季度成本优化方案:盘点当前账单结构 → 识别 5 个浪费点 → 每个点写 ROI(年节省 vs 实施成本 vs 风险)→ 排出优先级,形成一份可执行的 FinOps 报告。</li></ol><blockquote><p>用 <code>/practice system-design 成本与容量优化</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端</th><th>后端成本优化</th></tr></thead><tbody><tr><td>bundle 体积预算</td><td>云资源预算/成本告警</td></tr><tr><td>代码分割按需加载</td><td>按需实例/竞价实例</td></tr><tr><td>图片压缩/WebP</td><td>数据压缩/列存</td></tr><tr><td>HTTP 缓存策略</td><td>缓存降本(命中率)</td></tr><tr><td>长列表虚拟滚动</td><td>批处理/分页</td></tr><tr><td>Lighthouse 性能预算</td><td>成本 ROl 评估清单</td></tr><tr><td>静态资源 CDN</td><td>流量成本控制</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://www.finops.org/" target="_blank" rel="noreferrer">FinOps 基金会(云成本管理方法论)</a></li><li><a href="https://docs.aws.amazon.com/whitepapers/latest/cost-optimization/cost-optimization.html" target="_blank" rel="noreferrer">AWS 定价与成本管理文档</a></li><li><a href="https://cloud.google.com/architecture/framework/cost-optimization" target="_blank" rel="noreferrer">Google Cloud 成本管理最佳实践</a></li><li><a href="https://www.alibabacloud.com/help/zh/product-overview/billing-overview" target="_blank" rel="noreferrer">阿里云成本优化白皮书</a></li></ul>`,38)])])}const g=a(e,[["render",p]]);export{c as __pageData,g as default};
